head.script:
// 출력 영역 생성 전에 출력된 값 보관 (화면 로딩 중 발생한 이벤트용)
scwin.pendingList = [];

scwin.onpageload = function () {
    for (let i = 0; i < scwin.pendingList.length; i++) {
        scwin.setReturnValue(scwin.pendingList[i]);
    }
    scwin.pendingList = [];
    scwin.setReturnValue("[화면 로딩 완료] getValue : " + dp_ref.getValue());
};

scwin.dp_ref_onchange = function () {
    scwin.setReturnValue("onchange 발생 : " + dp_ref.getValue());
};

// 바인딩 데이터 변경 (정상 대조)
scwin.btn_dataSet_onclick = function (e) {
    scwin.setReturnValue("[바인딩 데이터 변경] dma_date.set('key1', '20261012')");
    dma_date.set("key1", "20261012");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    if (typeof tbx_return === "undefined" || !tbx_return) {
        scwin.pendingList.push(strValue);
        return;
    }
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
